const int ledPin = 13; // The pin connected to the LED
const int buttonPin = 2; // The pin connected to the pushbutton

void setup() {
  pinMode(ledPin, OUTPUT); // Set the LED pin as an output
  pinMode(buttonPin, INPUT_PULLUP); // Set the button pin as input with internal pull-up resistor enabled
}

void loop() {
  // Check if the button is pressed
  if (digitalRead(buttonPin) == LOW) {
    digitalWrite(ledPin, HIGH); // Turn on the LED
    delay(3000); // Wait for 3 seconds
    digitalWrite(ledPin, LOW); // Turn off the LED
  }
}
```

